catalog_script_client.script:
(function () {

    // The mapped questions are already copied onto "current":
    // vehicle, cited_person, cited_party_type, violation_type, parking_lot, short_description.
    // This script fills the gap for visitors and double-checks the rest.

    // ---------- 1. Visitor: find or create the vehicle ----------
    var notOnFile = producer.not_on_file.toString();   // 'true' (checkbox) or 'Yes' (Yes/No)

    if (notOnFile == 'true' || notOnFile == 'Yes') {
        var plate = producer.visitor_plate.toString().toUpperCase().replace(/ /g, '');
        var province = producer.visitor_state.toString();

        var newVehicle = new GlideRecord('x_1234_parking_c_0_vehicle');
        newVehicle.addQuery('plate', plate);
        newVehicle.addQuery('plate_state', province);
        newVehicle.query();

        if (newVehicle.next()) {
            current.vehicle = newVehicle.sys_id;           // plate already on file: reuse it
        } else {
            newVehicle.initialize();                       // new plate: create the vehicle
            newVehicle.plate = plate;
            newVehicle.plate_state = province;
            newVehicle.make = producer.visitor_make.toString();
            newVehicle.model = producer.visitor_model.toString();
            newVehicle.colour = producer.visitor_colour.toString();
            current.vehicle = newVehicle.insert();
        }
        current.cited_person_type = 'guest';
    }



})();
